import Foundation

// MARK: - Enums mirroring Rust

public enum Role {
    case sender
    case viewer
}

public enum ConnectionMode {
    case local
    case direct
    case internet
}

public enum SessionState {
    case idle
    case awaitingPeer
    case awaitingApproval
    case active
    case sharingInterrupted
    case ended
}

public enum SessionCommand {
    case startPairing
    case requestJoin
    case peerRequestedJoin
    case approveViewer
    case approvalReceived
    case captureStarted
    case captureStopped
    case end
}

public enum BridgeError: Error {
    case UnknownRoleCode(code: UInt8)
    case UnknownModeCode(code: UInt8)
    case UnknownCommandCode(code: UInt8)
    case RoleMismatch(expected: Role)
    case InvalidTransition(state: SessionState, command: SessionCommand)
    case ViewerAlreadyConnected
    case SessionEnded
}

// MARK: - Pure-Swift session implementation (mirrors core/src/session.rs)

public class GreenfieldSession {
    private var role: Role
    private var mode: ConnectionMode
    private var state: SessionState = .idle
    private var viewerConnected: Bool = false
    private var viewerApproved: Bool = false

    public init(role: Role, mode: ConnectionMode) {
        self.role = role
        self.mode = mode
    }

    public static func new(role: Role, mode: ConnectionMode) -> GreenfieldSession {
        return GreenfieldSession(role: role, mode: mode)
    }

    public static func fromCodes(roleCode: UInt8, modeCode: UInt8) throws -> GreenfieldSession {
        let r: Role
        switch roleCode {
        case 0: r = .sender
        case 1: r = .viewer
        default: throw BridgeError.UnknownRoleCode(code: roleCode)
        }
        let m: ConnectionMode
        switch modeCode {
        case 0: m = .local
        case 1: m = .direct
        case 2: m = .internet
        default: throw BridgeError.UnknownModeCode(code: modeCode)
        }
        return GreenfieldSession(role: r, mode: m)
    }

    public func role() -> Role { return role }
    public func mode() -> ConnectionMode { return mode }
    public func state() -> SessionState { return state }
    public func viewerApproved() -> Bool { return viewerApproved }

    public func roleCode() -> UInt8 {
        switch role {
        case .sender: return 0
        case .viewer: return 1
        }
    }

    public func connectionModeCode() -> UInt8 {
        switch mode {
        case .local: return 0
        case .direct: return 1
        case .internet: return 2
        }
    }

    public func stateCode() -> UInt8 {
        switch state {
        case .idle: return 0
        case .awaitingPeer: return 1
        case .awaitingApproval: return 2
        case .active: return 3
        case .sharingInterrupted: return 4
        case .ended: return 5
        }
    }

    public func apply(command: SessionCommand) throws -> SessionState {
        if state == .ended { throw BridgeError.SessionEnded }
        let next: SessionState
        switch command {
        case .end:
            next = .ended
        case .startPairing:
            guard role == .sender else { throw BridgeError.RoleMismatch(expected: .sender) }
            guard state == .idle else { throw BridgeError.InvalidTransition(state: state, command: command) }
            next = .awaitingPeer
        case .requestJoin:
            guard role == .viewer else { throw BridgeError.RoleMismatch(expected: .viewer) }
            guard state == .idle else { throw BridgeError.InvalidTransition(state: state, command: command) }
            next = .awaitingApproval
        case .peerRequestedJoin:
            guard role == .sender else { throw BridgeError.RoleMismatch(expected: .sender) }
            if viewerConnected { throw BridgeError.ViewerAlreadyConnected }
            guard state == .awaitingPeer else { throw BridgeError.InvalidTransition(state: state, command: command) }
            viewerConnected = true
            next = .awaitingApproval
        case .approveViewer:
            guard role == .sender else { throw BridgeError.RoleMismatch(expected: .sender) }
            guard state == .awaitingApproval else { throw BridgeError.InvalidTransition(state: state, command: command) }
            viewerApproved = true
            next = .active
        case .approvalReceived:
            guard role == .viewer else { throw BridgeError.RoleMismatch(expected: .viewer) }
            guard state == .awaitingApproval else { throw BridgeError.InvalidTransition(state: state, command: command) }
            viewerApproved = true
            next = .active
        case .captureStarted:
            guard state == .sharingInterrupted else { throw BridgeError.InvalidTransition(state: state, command: command) }
            next = .active
        case .captureStopped:
            guard state == .active else { throw BridgeError.InvalidTransition(state: state, command: command) }
            next = .sharingInterrupted
        }
        state = next
        return next
    }

    public func sendCommand(commandCode: UInt8) throws -> UInt8 {
        let cmd: SessionCommand
        switch commandCode {
        case 0: cmd = .startPairing
        case 1: cmd = .requestJoin
        case 2: cmd = .peerRequestedJoin
        case 3: cmd = .approveViewer
        case 4: cmd = .approvalReceived
        case 5: cmd = .captureStarted
        case 6: cmd = .captureStopped
        case 7: cmd = .end
        default: throw BridgeError.UnknownCommandCode(code: commandCode)
        }
        let newState = try apply(command: cmd)
        return newStateCode(newState)
    }

    private func newStateCode(_ s: SessionState) -> UInt8 {
        switch s {
        case .idle: return 0
        case .awaitingPeer: return 1
        case .awaitingApproval: return 2
        case .active: return 3
        case .sharingInterrupted: return 4
        case .ended: return 5
        }
    }
}

