    return "0.1.0-stub"
}

public func roleSenderCode() -> UInt8 { return 0 }
public func roleViewerCode() -> UInt8 { return 1 }
public func modeLocalCode() -> UInt8 { return 0 }
public func modeDirectCode() -> UInt8 { return 1 }
public func modeInternetCode() -> UInt8 { return 2 }
